case value in
  pipe) first | second ;;
  and) third && fourth ;&
  or) fifth || sixth ;;
  final) seventh || eighth
esac

summarize() {
  case value in
    first)
      before
      ;;
    second)
      condition || invalid_input
      ;;
  esac
}

